// components/Customized.jsx  (or app/components/Customized.jsx in App Router)

import Image from 'next/image';

const Customized = () => {
  const services = [
    {
      icon: '/topnotch.webp',
      title: 'Top Notch Quality',
      description: 'Topnotch quality in bridal service is by exceptional expertise.',
    },
    {
      icon: '/makeover.webp',
      title: 'Personalised Makeup',
      description: 'A key component of superior quality in bridal services is customized makeup.',
    },
    {
      icon: '/adept.webp',
      title: 'Experienced Stylists',
      description: 'A professional stylist is essential to get excellent bridal services.',
    },
    {
      icon: '/route.webp',
      title: 'All Locations',
      description: 'Our bridal service in Tamil Nadu and Andhra thrives on personalized attention and care.',
    },
  ];

  return (
    <div className="text-center">
      {/* Title */}
      <h2 className="text-2xl font-bold text-[#9e0000] mt-[3%]">
        Our Services
      </h2>

      {/* Subtitle */}
      <h3 className="text-5xl font-bold text-[#6c09ae] mb-8 font-serif
                     max-[480px]:text-2xl
                     min-[841px]:max-[1107px]:text-3xl">
        Bridal Service Customized For You
      </h3>

      {/* Grid */}
      <div className="grid gap-4 p-[30px]
                      [grid-template-columns:repeat(auto-fit,minmax(250px,2fr))]
                      max-[480px]:grid-cols-1 max-[480px]:-mt-[50px] max-[480px]:gap-4
                      min-[841px]:max-[1107px]:grid-cols-2 min-[841px]:max-[1107px]:gap-4 min-[841px]:max-[1107px]:p-5">
        {services.map((service, index) => (
          <div
            key={index}
            className="bg-white border border-[#9e0000] rounded-lg p-6 text-center
                       shadow-[0px_7px_15px_rgb(36,155,202)]
                       transition-transform duration-300 ease-in-out
                       hover:-translate-y-[10px] hover:shadow-[0px_10px_20px_purple]
                       max-[480px]:p-3 max-[480px]:m-2
                       min-[841px]:max-[1107px]:p-4"
          >
            {/* Icon */}
            <div className="mb-4">
              <Image
                src={service.icon}
                alt={`${service.title} Icon`}
                width={80}
                height={80}
                className="w-[30%] h-auto mx-auto"
              />
            </div>

            {/* Card Title */}
            <h4 className="text-xl font-bold text-[rgb(255,68,0)] mb-[2px]
                           max-[480px]:text-lg
                           min-[841px]:max-[1107px]:text-lg">
              {service.title}
            </h4>

            {/* Description */}
            <p className="text-base text-[#333333]
                          max-[480px]:text-sm">
              {service.description}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Customized;